insert into public.email_hero_images (source,title,year,image_url,caption,subject_hook,style,accent,credit) values
  ('tmdb','Sinners',null,'https://image.tmdb.org/t/p/w1280/nAxGnGHOsfzufThz20zgmRwKur3.jpg','Some rooms change what walks out of them. Three New York projects are casting this week.','Some rooms change what walks out of them','latenight','#D48934','Still: Sinners'),
  ('tmdb','Wicked',null,'https://image.tmdb.org/t/p/w1280/fyZ6SDUS4o9jp2EHxfZa3qS9ean.jpg','Every ensemble you''ve ever loved started as a room full of people nobody had cast yet.','Every ensemble you love started as an open call','marquee','#E0B08E','Still: Wicked'),
  ('tmdb','Weapons',null,'https://image.tmdb.org/t/p/w1280/8VyTWJrNEyV2MTWvniDVp0MpOAe.jpg','Everyone in town saw it. Nobody can describe it. Today''s roles are below.','Nobody can describe it. You can audition for it','latenight','#4D96BB','Still: Weapons'),
  ('tmdb','Dune Part Two',null,'https://image.tmdb.org/t/p/w1280/eZ239CUp1d6OryZEBPnO2n87gMG.jpg','The desert doesn''t audition you twice. Neither does a casting director''s inbox.','The desert doesn''t audition you twice','marquee','#BB8B4D','Still: Dune Part Two'),
  ('tmdb','Anora',null,'https://image.tmdb.org/t/p/w1280/qvyOfwTC3qdbzkqdXWSSEMHtjBZ.jpg','The best performances of the year came from faces nobody knew in January.','January unknowns, December leads','latenight','#C68E69','Still: Anora'),
  ('tmdb','The Substance',null,'https://image.tmdb.org/t/p/w1280/8ODNt5olCeIqBYTP3GgXEQYTfeX.jpg','The industry''s favourite horror is being replaced. Here''s work that wants you as you are.','Roles that want you exactly as you are','marquee','#C76C72','Still: The Substance'),
  ('tmdb','Conclave',null,'https://image.tmdb.org/t/p/w1280/eZzNdjNDvaSoyywy9ICg2UmFwul.jpg','A room of people deciding. On the other side of the door, someone waiting to hear.','Someone is on the other side of that door','latenight','#F41470','Still: Conclave'),
  ('tmdb','Twisters',null,'https://image.tmdb.org/t/p/w1280/58D6ZAvOKxlHjyX9S8qNKSBE9Y.jpg','Chasing the thing everyone else runs from is the entire job description.','Chasing what everyone else runs from','marquee','#BB794D','Still: Twisters'),
  ('public_domain','Nosferatu',1922,'https://image.tmdb.org/t/p/w1280/cA9iGtvjRGJHzDBfrq48l0eyCvA.jpg','A hundred and four years on, it still works — shadow, silence, and one unbearable face.','Shadow, silence, and one unbearable face','latenight','#B5BB4E','Still: Nosferatu'),
  ('public_domain','The General',1926,'https://image.tmdb.org/t/p/w1280/mzox4HbcV9W42MH2dB1QsdDVGo3.jpg','The most expensive shot of the silent era. Done once, in a single take.','One take. No second chance','marquee','#BB4D4D','Still: The General'),
  ('public_domain','Metropolis',1927,'https://image.tmdb.org/t/p/w1280/eeMoFKxjjiCi6iep2GEZtSAMYIr.jpg','They built the future out of extras. Thousands of them, uncredited, unforgettable.','They built the future out of extras','latenight','#BB4D4D','Still: Metropolis'),
  ('tmdb','F1',null,'https://image.tmdb.org/t/p/w1280/lkDYN0whyE82mcM20rwtwjbniKF.jpg','Ninety seconds of finished footage, six weeks of shooting. Screen time is earned.','Six weeks of shooting, ninety seconds on screen','marquee','#4DA9BB','Still: F1'),
  ('public_domain','Sherlock Jr.',1924,'https://image.tmdb.org/t/p/w1280/tSipsYTp565LkopntX1lZNLPYHP.jpg','Keaton did his own stunts because nobody else would. Start where you can.','Keaton did his own stunts. Start where you can','latenight','#D7D797','Still: Sherlock Jr.'),
  ('tmdb','Superman',2025,'https://image.tmdb.org/t/p/w1280/eGX66zonvc4bXg3rM08RUxdYSDx.jpg','Someone has to play the person everyone has already pictured. Might as well be you.','Someone has to play him','marquee','#4278C6','Still: Superman'),
  ('tmdb','Night of the Living Dead',1968,'https://image.tmdb.org/t/p/w1280/5KtmBSqFtHY3I9t8lgH27Mc0bqY.jpg','Shot for $114,000 by people with no permission. That''s still how most films start.','$114,000 and nobody''s permission','latenight','#BB4D75','Still: Night of the Living Dead'),
  ('tmdb','Challengers',null,'https://image.tmdb.org/t/p/w1280/tq8COKsI99Bivjd4CZIYVGoKcIx.jpg','Three people, one court, nowhere to hide. That is what a good audition feels like.','Three people and nowhere to hide','marquee','#71B3D0','Still: Challengers'),
  ('tmdb','Carnival of Souls',1962,'https://image.tmdb.org/t/p/w1280/esIoQw7VaykfHsw6fx2VltZ1R7U.jpg','One organ, one lake, one actress. You don''t need a budget to be remembered.','One lake, one actress, no budget','latenight','#BB4D4D','Still: Carnival of Souls'),
  ('tmdb','The Wild Robot',null,'https://image.tmdb.org/t/p/w1280/mQZJoIhTEkNhCYAqcHrQqhENLdu.jpg','Your voice is a credit too. Some of today''s roles never face a camera.','Some of today''s roles never face a camera','marquee','#66C4E8','Still: The Wild Robot'),
  ('tmdb','His Girl Friday',1940,'https://image.tmdb.org/t/p/w1280/ihoQaiMFAz4YCTAaSIsQjRknsNH.jpg','Nobody has talked that fast since. Ninety takes of pure nerve.','Ninety takes of pure nerve','latenight','#C36262','Still: His Girl Friday'),
  ('tmdb','Wicked For Good',null,'https://image.tmdb.org/t/p/w1280/cGbPBHKSFO7hSIjxkb3KOaGdOep.jpg','Standing at the back of the number is how most leads started.','The back of the number is where leads start','marquee','#DEC690','Still: Wicked For Good'),
  ('tmdb','Detour',1945,'https://image.tmdb.org/t/p/w1280/uGOKN4VeCsf249zypWfaAzfTxAB.jpg','Six days, one road, no money. Noir was built by people improvising.','Six days, one road, no money','latenight','#BB4D4D','Still: Detour'),
  ('tmdb','Jurassic World Rebirth',null,'https://image.tmdb.org/t/p/w1280/zNriRTr0kWwyaXPzdg1EIxf0BWk.jpg','Reacting convincingly to nothing at all is a real skill. It pays, too.','Reacting to nothing at all, convincingly','marquee','#C0885A','Still: Jurassic World Rebirth'),
  ('tmdb','Thunderbolts',null,'https://image.tmdb.org/t/p/w1280/rthMuZfFv4fqEU4JVbgSW9wQ8rs.jpg','The ensemble is where careers start. Every one of them was an unknown once.','The ensemble is where careers start','latenight','#CCB079','Still: Thunderbolts'),
  ('public_domain','The Cabinet of Dr. Caligari',1920,'https://image.tmdb.org/t/p/w1280/sLq72hBx8Xs2IISVsZJqgjOd31b.jpg','The set was painted crooked on purpose. People are still copying it.','They painted the set crooked on purpose','marquee','#BB4D4D','Still: The Cabinet of Dr. Caligari'),
  ('tmdb','A Complete Unknown',null,'https://image.tmdb.org/t/p/w1280/otugS74HEHdca4aTCtt8HtXvPYV.jpg','Nobody knew his name in 1961 either.','Nobody knew his name in 1961 either','latenight','#D7CA97','Still: A Complete Unknown'),
  ('public_domain','Safety Last!',1923,'https://image.tmdb.org/t/p/w1280/3zo6ZONR4Mth2nWFbQK9dhCWbVz.jpg','He really did hang off the clock. Always ask what the role actually requires.','He really did hang off the clock','marquee','#634DBB','Still: Safety Last!'),
  ('tmdb','Gladiator II',null,'https://image.tmdb.org/t/p/w1280/tOqIwliWMovSIZ9DyvHcHI7p2im.jpg','Thousands of extras. One of them is in every frame you remember.','One extra is in every frame you remember','latenight','#C27346','Still: Gladiator II'),
  ('public_domain','The Kid',1921,'https://image.tmdb.org/t/p/w1280/mAhCW7QbpL5kwvCWGsfyY3ILoW6.jpg','Chaplin auditioned hundreds of children. Jackie Coogan was four.','Chaplin auditioned hundreds. Coogan was four','marquee','#D7B797','Still: The Kid'),
  ('tmdb','Nickel Boys',null,'https://image.tmdb.org/t/p/w1280/kmLssINCNdXnIDjWkBsk6LUNSbe.jpg','Shot almost entirely in first person. The camera was somebody''s eyes.','The camera was somebody''s eyes','latenight','#C19B5C','Still: Nickel Boys'),
  ('public_domain','The Phantom of the Opera',1925,'https://image.tmdb.org/t/p/w1280/6FSs7jMimg1PBYdhZtPNQhtKtEc.jpg','Chaney designed his own makeup and refused to show it before the premiere.','He would not show the makeup before the premiere','latenight','#BB4D4D','Still: The Phantom of the Opera'),
  ('tmdb','D.O.A.',1949,'https://image.tmdb.org/t/p/w1280/rsl2YCe2bSeni2qGdaMoDBS7sLo.jpg','A man walks into a police station to report his own murder. Openings matter.','He walked in to report his own murder','latenight','#4D4DBB','Still: D.O.A.'),
  ('tmdb','Charade',1963,'https://image.tmdb.org/t/p/w1280/gj2TBYmOIy4E2GjMIpnbAEZNCQx.jpg','It fell into the public domain by accident, and everyone has watched it since.','Public domain by accident','latenight','#BB894D','Still: Charade')
